import { fileURLToPath } from 'node:url';

import { drizzle } from 'drizzle-orm/node-postgres';
import { migrate } from 'drizzle-orm/node-postgres/migrator';
import pg from 'pg';

/** Folder with the SQL migrations generated by drizzle-kit (apps/api/drizzle). */
export const MIGRATIONS_FOLDER = fileURLToPath(new URL('../../../drizzle', import.meta.url));

/**
 * Applies pending migrations. Must run as az_owner (DATABASE_MIGRATION_URL):
 * az_app has no permission to create or alter tables.
 */
export const runMigrations = async (migrationUrl: string): Promise<void> => {
  const pool = new pg.Pool({ connectionString: migrationUrl, max: 1 });
  try {
    await migrate(drizzle(pool), { migrationsFolder: MIGRATIONS_FOLDER });
  } finally {
    await pool.end();
  }
};
